using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
using UsbRecovery;

// Optional local integration. Neither the8GiB image nor external oracle is
// downloaded, generated by this reader or silently substituted with fixtures.
public static class RefsNativeEngineTests
{
    const string SourceSha = "246d3c2f969ff6a67d6a9879723de50c20152b0e11d61034e38c4c7851c24ffc";
    static int checks;
    static readonly JavaScriptSerializer Json = new JavaScriptSerializer { MaxJsonLength = 64*1024*1024 };
    static void Check(bool value,string why) { checks++; if (!value) throw new IOException(why); }
    static void Set(object owner,string name,object value) { owner.GetType().GetField(name).SetValue(owner,value); }
    static string Hash(string path) { return RecoveryCore.HashFile(path,CancellationToken.None,(a,b) => { }); }
    static string Parent(string root) { return Path.Combine(root,"anchor.json"); }
    static RecoveryMethodCheckpoint Anchor(string root)
    { return File.Exists(Parent(root)) ? Json.Deserialize<RecoveryMethodCheckpoint>(File.ReadAllText(Parent(root),Encoding.UTF8)) : null; }
    static void Save(string root,RecoveryMethodCheckpoint value)
    {
        string temp = Parent(root)+"."+Guid.NewGuid().ToString("N")+".partial"; byte[] bytes = Encoding.UTF8.GetBytes(Json.Serialize(value));
        using (var file = new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.Read)) { file.Write(bytes,0,bytes.Length); file.Flush(true); }
        if (File.Exists(Parent(root))) File.Replace(temp,Parent(root),null); else File.Move(temp,Parent(root));
    }
    static RefsRecovery.Report Run(string image,string root,CancellationToken token,Action<string> progress)
    {
        using (var input = new FileStream(image,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)) {
            object c = Activator.CreateInstance(typeof(RefsRecovery).GetNestedType("Context",BindingFlags.NonPublic),true);
            Set(c,"Input",input); Set(c,"Root",Path.Combine(root,"refs")); Set(c,"Cancel",token);
            // The independent content oracle covers live metadata traversal;
            // unreferenced scan is explicitly disabled and reported limited.
            Set(c,"Limits",new RefsRecovery.Limits { MaximumSalvageBlocks = 0 });
            object context = Activator.CreateInstance(typeof(RefsRecovery).Assembly.GetType("UsbRecovery.RecoveryCheckpointContext",true),true);
            Set(context,"Directory",root); Set(context,"Method","refs"); Set(context,"SourceSha256",SourceSha); Set(context,"Settings","native-full-live-refs-v1");
            Set(context,"Resume",Anchor(root)); Set(context,"Commit",(Action<RecoveryMethodCheckpoint>)(a => Save(root,a)));
            try { typeof(RefsRecovery).GetMethod("RecoverCheckpointedCore",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[] { c,context,null,progress }); }
            catch (TargetInvocationException error) { throw error.InnerException; }
            return (RefsRecovery.Report)c.GetType().GetField("Report").GetValue(c);
        }
    }
    public static int Main(string[] args)
    {
        try {
            string image = Path.GetFullPath(args[0]),oraclePath = Path.GetFullPath(args[1]),root = Path.GetFullPath(args[2]);
            bool existing = args.Length == 4 && args[3] == "--verify-existing";
            if (existing) { if (!Directory.Exists(root) || !File.Exists(Parent(root))) throw new IOException("Existing anchored native run required"); }
            else { if (Directory.Exists(root) || File.Exists(root)) throw new IOException("Fresh native evidence directory required"); Directory.CreateDirectory(root); }
            var oracle = Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(oraclePath,Encoding.UTF8));
            Check((string)oracle["status"] == "passed" && (string)oracle["source_raw_sha256"] == SourceSha &&
                (string)oracle["source_repo_commit"] == "d4d5fd28942eb14ebe11d90f4eb9342f5e3d7b92","provided independent forefst oracle binds the exact known source");
            Check(new FileInfo(image).Length == 8589934592L && (File.GetAttributes(image)&FileAttributes.SparseFile) == 0 && Hash(image) == SourceSha,"native source is the pinned materialized8GiB image");
            bool cancelled = false,denied = false;
            if (!existing) using (var cancel = new CancellationTokenSource()) {
                try { Run(image,root,cancel.Token,m => {
                    if (!denied && m.StartsWith("refs: metadata unit ",StringComparison.Ordinal)) {
                        try { using (var write = new FileStream(image,FileMode.Open,FileAccess.Write,FileShare.ReadWrite)) { } }
                        catch (IOException) { denied = true; }
                        Check(denied,"shared verified source lease denies an actual write-open");
                    }
                    if (m == "refs: file 0 complete") cancel.Cancel();
                }); } catch (OperationCanceledException) { cancelled = true; }
            }
            if (!existing) Check(cancelled && Anchor(root) != null,"native full controller stops with first file durably completed");
            else Check(Anchor(root) != null && File.Exists(Path.Combine(root,"refs","report.json")),"previous completed native result is verified without restarting its traversal");
            var report = Run(image,root,CancellationToken.None,null);
            var expected = ((System.Collections.IEnumerable)oracle["records"]).Cast<Dictionary<string,object>>().ToDictionary(row => (string)row["path"],StringComparer.Ordinal);
            Check(expected.Count == 776 && report.RecoveredFiles == 776 && report.Entries.Count == 776 && report.OutputBytes == 862148781L,
                "native full current traversal recovers exactly the oracle776files and byte total");
            foreach (var entry in report.Entries) {
                Dictionary<string,object> row;
                Check(expected.TryGetValue(entry.RelativePath,out row) && entry.DeclaredSize == Convert.ToInt64(row["expected_size"]) &&
                    entry.Sha256 == (string)row["oracle_sha256"] && entry.Status == "recovered_live","native entry size/path/digest agrees with independent forefst");
                string payload = RecoveryCatalog.SafeFile(Path.Combine(root,"refs"),entry.Output);
                Check(new FileInfo(payload).Length == entry.DeclaredSize && Hash(payload) == entry.Sha256,"native published payload bytes match independent digest");
            }
            Check(report.SourceUnchanged && report.Limited && report.Status == "limited" && report.Skipped.ContainsKey("unreferenced_scan_limit") && Hash(image) == SourceSha,
                "full native source is unchanged and disabled salvage remains explicitly limited");
            File.WriteAllText(Path.Combine(root,"native-acceptance.json"),Json.Serialize(new { status="passed",checks,verified_existing=existing,source_sha256=SourceSha,
                oracle_sha256=Hash(oraclePath),app_sha256=Hash(typeof(RefsRecovery).Assembly.Location),files=report.RecoveredFiles,bytes=report.OutputBytes,
                scope="current managed ReFS full live-file traversal with cancel/resume vs pinned independent forefst oracle; no unreferenced/deleted/native-other-version/device proof" }),new UTF8Encoding(false));
            Console.WriteLine("PASS RefsNativeEngine: "+checks+" checks;776 native live files; unreferenced scan disabled"); return 0;
        } catch (Exception error) { Console.Error.WriteLine(error); return 1; }
    }
}
